const money=v=>'R$ '+new Intl.NumberFormat('pt-BR',{notation:v>=1e6?'compact':'standard',maximumFractionDigits:v>=1e6?2:0}).format(v);
const fullMoney=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(v);
const iconFor=name=>channels.find(c=>[c.name,...(c.aliases||[])].some(a=>name.toLowerCase().includes(a.toLowerCase())))||{name,short:name.slice(0,2).toUpperCase(),color:'#444'};
const iconHtml=c=>c.domain?`<img src="https://www.google.com/s2/favicons?domain=${c.domain}&sz=64" alt="Logo ${c.name}" referrerpolicy="no-referrer">`:c.short;
function totals(){return data.map(d=>({...d,total:Number(currentChannels[d.channel]||0)})).filter(d=>d.total>0).sort((a,b)=>b.total-a.total)}
function renderEmpty(){const zero=money(0);document.querySelector('#totalGMV').textContent=zero;document.querySelector('#hourGMV').textContent=zero;document.querySelector('#currentHour').textContent='—';document.querySelector('#totalDelta').textContent='Aguardando primeira carga';document.querySelector('#hourDelta').textContent='Sem snapshot registrado';document.querySelector('#leaderName').textContent='Aguardando vendas';document.querySelector('#leaderShare').textContent='0% do GMV';document.querySelector('#leaderIcon').innerHTML='—';document.querySelector('#leaderProgress').style.width='0';document.querySelector('#targetValue').textContent='0.0%';document.querySelector('#targetProgress').style.width='0';document.querySelector('#targetGap').textContent='Aguardando primeira carga do dia';['ordersKpi','activeKpi'].forEach(id=>document.querySelector('#'+id).textContent='0');document.querySelector('#ticketKpi').textContent=zero;document.querySelector('#activeLabel').textContent='Nenhum canal carregado';document.querySelector('#top3Kpi').textContent='0.0%';document.querySelector('#paceKpi').textContent='Aguardando';document.querySelector('#paceLabel').textContent='Sem histórico horário';document.querySelector('#rankingPage').textContent='0 CANAIS ATIVOS';document.querySelector('#ranking').innerHTML='<div class="empty-state">A primeira carga de hoje ainda não foi disponibilizada.</div>';document.querySelector('#tickerTrack').innerHTML='<span>AGUARDANDO PRIMEIRA CARGA DO DIA</span>';document.querySelector('#insightText').textContent='O painel começará a registrar o histórico a partir da primeira atualização com dados.';document.querySelector('#chartTitle').textContent='GMV HORA A HORA';document.querySelector('#chartLegend').innerHTML='<i class="orange"></i> Aguardando primeiro snapshot';document.querySelector('#axis').innerHTML=[0,0,0,0,0].map(money).map(v=>`<span>${v}</span>`).join('');document.querySelector('#hourlyChart').innerHTML=['08h','09h','10h','11h','12h','13h','14h','15h','16h','17h','18h','19h','20h','21h','22h','23h'].map(h=>`<div class="bar-group"><div class="bar" style="height:2px"></div><label>${h}</label></div>`).join('');document.querySelector('#peakLabel').textContent='Nenhuma venda carregada';document.querySelector('#sparkline').innerHTML='';lastRanking=[];lastRankingTotal=0}
function render(){
  if(!data.length)return renderEmpty();
  const ranked=totals(),total=Number(liveMetrics.totalGmv||ranked.reduce((s,d)=>s+d.total,0)),activeHour=Number.isFinite(Number(liveMetrics.activeHour))?Number(liveMetrics.activeHour):Math.max(0,new Date().getHours());
  const confirmed=snapshotHistory.filter(x=>!x.isBaseline),hourTotal=Number(liveMetrics.hourGmv||0),previousAccum=Math.max(0,total-hourTotal),delta=previousAccum>1?(hourTotal/previousAccum)*100:0,hasComparison=confirmed.length>0&&previousAccum>1;
  document.querySelector('#totalGMV').textContent=money(total);document.querySelector('#hourGMV').textContent=money(hourTotal);document.querySelector('#currentHour').textContent=`${String(activeHour).padStart(2,'0')}h`;
  const reconciled=Boolean(liveMetrics.hourIsReconciled),previousHour=Number(liveMetrics.previousHourGmv||0),hourChange=previousHour?(hourTotal/previousHour-1)*100:null;document.querySelector('#hourDelta').textContent=reconciled?`Carga reconciliada até ${String(activeHour).padStart(2,'0')}h`:hourChange===null?'Hora em andamento':`${hourChange>=0?'▲':'▼'} ${Math.abs(hourChange).toFixed(1)}% vs. hora anterior`;document.querySelector('#hourDelta').style.color=reconciled?'#ffb020':hourChange===null?'var(--muted)':hourChange>=0?'var(--green)':'#ff6262';
  document.querySelector('#totalDelta').textContent=reconciled?'Atualizado com dados reconciliados':hasComparison?`▲ ${delta.toFixed(1)}% na janela atual`:'Acompanhamento em tempo real';
  document.querySelector('#hourProgress').style.width=Math.min(100,hourTotal/300000*100)+'%';
  const leader=ranked[0],li=iconFor(leader.channel);document.querySelector('#leaderName').textContent=leader.channel;document.querySelector('#leaderShare').textContent=`${(leader.total/total*100).toFixed(1)}% do GMV`;
  Object.assign(document.querySelector('#leaderIcon').style,{background:li.color,color:li.ink||'#fff'});document.querySelector('#leaderIcon').innerHTML=iconHtml(li);document.querySelector('#leaderProgress').style.width=(leader.total/total*100)+'%';
  const target=dailyTarget,pct=target?total/target*100:0;document.querySelector('#targetLabel').textContent=target?money(target):'SEM META';document.querySelector('#targetValue').textContent=target?pct.toFixed(1)+'%':'—';document.querySelector('#targetProgress').style.width=Math.min(100,pct)+'%';document.querySelector('#targetGap').textContent=!target?'Meta não cadastrada para a data':total>=target?`Meta superada em ${money(total-target)}`:`Faltam ${money(target-total)} para a meta`;
  const top3=ranked.slice(0,3).reduce((s,d)=>s+d.total,0);document.querySelector('#ordersKpi').textContent=new Intl.NumberFormat('pt-BR').format(liveMetrics.totalOrders||0);document.querySelector('#hourOrdersKpi').textContent=new Intl.NumberFormat('pt-BR').format(liveMetrics.hourOrders||0);document.querySelector('#ticketKpi').textContent=money(liveMetrics.ticket||0);document.querySelector('#activeKpi').textContent=ranked.filter(d=>d.total>0).length;document.querySelector('#activeLabel').textContent=`${ranked.filter(d=>d.total>0).length} canais com venda`;document.querySelector('#top3Kpi').textContent=(total?top3/total*100:0).toFixed(1)+'%';setComparison('dod',comparisons.dod,comparisons.previousDayGmv);setComparison('mom',comparisons.mom,comparisons.previousMonthGmv);document.querySelector('#paceKpi').textContent=reconciled?'Reconciliado':!hasComparison?'Monitorando':delta>5?'Acelerando':'Estável';document.querySelector('#paceKpi').style.color=reconciled?'#ffb020':delta>5?'var(--green)':'#fff';document.querySelector('#paceLabel').textContent=reconciled?'Janela histórica recuperada':hasComparison?`${delta>=0?'+':''}${delta.toFixed(1)}% na hora atual`:'Aguardando evolução da hora';document.querySelector('#insightText').textContent=`${leader.channel} lidera com ${(leader.total/total*100).toFixed(1)}% do GMV; Top 3 concentram ${(top3/total*100).toFixed(1)}% das vendas.`;
  lastRanking=ranked;lastRankingTotal=total;rankingPage=Math.min(rankingPage,Math.max(0,Math.ceil(ranked.length/8)-1));renderRanking(ranked,total);renderTicker(ranked);renderChart();renderSpark();
}
function setComparison(prefix,value,base){const kpi=document.querySelector('#'+prefix+'Kpi'),label=document.querySelector('#'+prefix+'Label');if(!kpi||!label)return;kpi.className='';if(value===null||value===undefined){kpi.textContent='—';label.textContent='Sem histórico comparável';return}kpi.textContent=`${value>=0?'▲':'▼'} ${Math.abs(value).toFixed(1)}%`;kpi.classList.add(value>=0?'positive':'negative');label.textContent=`Base ${money(base||0)}`}
function renderRanking(ranked,total){const max=ranked[0]?.total||1,container=document.querySelector('#ranking');document.querySelector('#rankingPage').textContent=`${ranked.length} CANAIS ATIVOS`;container.className='ranking '+(ranked.length>10?'dense':'');container.innerHTML=ranked.map((d,i)=>{const c=iconFor(d.channel),previous=Number(previousChannels[d.channel]||0),change=previous?(d.total/previous-1)*100:d.total>0?100:0,medal=i===0?'🥇':i===1?'🥈':i===2?'🥉':String(i+1).padStart(2,'0');return `<div class="rank-row ${i<3?'podium rank-'+(i+1):''}"><div class="place">${medal}</div><div class="channel-icon" style="background:${c.color};color:${c.ink||'#fff'}">${iconHtml(c)}</div><div class="channel-name"><strong>${d.channel}</strong><small>${(d.total/total*100).toFixed(1)}% participação</small></div><div class="rank-bar"><i style="width:${d.total/max*100}%"></i></div><div class="gmv"><strong>${money(d.total)}</strong><small style="color:${change>=0?'var(--green)':'#ff6262'}">${change>=0?'▲':'▼'} ${Math.abs(change).toFixed(1)}%</small></div></div>`}).join('')}
function renderTicker(ranked){const content=ranked.map((d,i)=>`<span><b>#${i+1}</b> ${d.channel} <strong>${money(d.total)}</strong></span>`).join('<i>◆</i>');document.querySelector('#tickerTrack').innerHTML=content+content}
function renderChart(){
  document.querySelector('#chartTitle').textContent='GMV INCREMENTAL POR HORA';
  if(perspectiveViews.find(view=>view.scope===activeScope)?.hourlyUnavailable){document.querySelector('#axis').innerHTML='';document.querySelector('#hourlyChart').innerHTML='<div class="empty-state">O histórico legado contém a evolução consolidada. Selecione Consolidado para consultar as capturas do dia.</div>';document.querySelector('#peakLabel').textContent='Histórico por operação indisponível';document.querySelector('#chartLegend').textContent='Acumulados por operação preservados';return}
  document.querySelector('#chartLegend').innerHTML=isUpdating?'<i class="orange"></i> Consolidando novos pedidos por hora':'<i class="orange"></i> Cada barra contém somente as vendas da respectiva hora';
  if(!data.length){document.querySelector('#axis').innerHTML=[0,0,0,0,0].map(money).map(v=>`<span>${v}</span>`).join('');document.querySelector('#hourlyChart').innerHTML='';document.querySelector('#peakLabel').textContent='Nenhuma venda registrada';return}
  const currentHour=selectedDate===todayDate?Number(new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',hour12:false}).format(new Date())):23;
  const rows=activeChannel==='all'?data:data.filter(d=>d.channel===activeChannel);
  const points=hours.slice(0,currentHour+1).map((label,hourIndex)=>({
    label,
    hourIndex,
    value:rows.reduce((sum,row)=>sum+Math.max(0,Number(row.hours[hourIndex]?.value||0)),0)
  }));
  const rawMax=Math.max(...points.map(p=>p.value),1),target=rawMax*1.18,magnitude=10**Math.floor(Math.log10(target)),normalized=target/magnitude;
  const scale=[1,2,2.5,5,10].find(step=>normalized<=step)*magnitude;
  document.querySelector('#axis').innerHTML=[scale,scale*.75,scale*.5,scale*.25,0].map(money).map(v=>`<span>${v}</span>`).join('');
  document.querySelector('#hourlyChart').innerHTML=points.map(p=>`<div class="bar-group ${p.hourIndex===currentHour?'latest':''}" title="${p.label}: ${fullMoney(p.value)}"><div class="bar" style="height:${Math.max(p.value?2:0,p.value/scale*100)}%" data-value="${fullMoney(p.value)}" role="img" aria-label="${p.label}, ${fullMoney(p.value)}"></div><label>${p.label}</label></div>`).join('');
  const peak=points.reduce((best,p)=>!best||p.value>best.value?p:best,null);document.querySelector('#peakLabel').textContent=peak?.value?`Pico horário: ${peak.label} • ${money(peak.value)}`:'Nenhuma venda registrada';
}
function renderSpark(){const currentHour=selectedDate===todayDate?Number(new Intl.DateTimeFormat('en-GB',{timeZone:'America/Sao_Paulo',hour:'2-digit',hour12:false}).format(new Date())):23;let vals=hours.slice(0,currentHour+1).map((_,i)=>data.reduce((s,d)=>s+(d.hours[i]?.value||0),0)),max=Math.max(...vals),min=Math.min(...vals),den=Math.max(vals.length-1,1),pts=vals.map((v,i)=>`${i/den*116},${36-(v-min)/(max-min||1)*32}`).join(' ');document.querySelector('#sparkline').innerHTML=`<svg viewBox="0 0 118 38"><polyline points="${pts}" fill="none" stroke="#ff6410" stroke-width="2"/><polyline points="0,38 ${pts} 118,38" fill="#ff5a0015" stroke="none"/></svg>`}
function stamp(){document.querySelector('#lastUpdate').textContent=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date())}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}
function renderManagement(){const row=name=>management.find(x=>x.grupo===name)||{gmv:0,pedidos:0,ticket:0},bind=(prefix,name)=>{const item=row(name);document.querySelector('#'+prefix+'Gmv').textContent=money(item.gmv);document.querySelector('#'+prefix+'Orders').textContent=new Intl.NumberFormat('pt-BR').format(item.pedidos);document.querySelector('#'+prefix+'Ticket').textContent=money(item.ticket)};bind('official','Oficial');bind('prioriza','Prioriza');bind('consolidated','Consolidado');document.querySelector('#officialCoreGmv').textContent=money(row('Oficial Core').gmv);document.querySelector('#fullOfficialGmv').textContent=money(row('Full Oficial').gmv);const health=document.querySelector('.stream-health'),label=health.querySelector('span');label.textContent=streamingStatus.kafka?'KAFKA + REDIS ATIVOS':streamingStatus.redis?'REDIS + API INCREMENTAL':'API INCREMENTAL';health.classList.toggle('fallback',!streamingStatus.kafka)}
function renderOperational(){const alert=document.querySelector('#smartAlert'),alerts=operational.alerts||[];alert.hidden=!alerts.length;alert.textContent=alerts.length?'⚠ '+alerts.map(item=>item.message).join('  •  '):''}
function applyConsolidated(){const scope='Consolidado';const view=perspectiveViews.find(item=>item.scope===scope);if(!view)return;activeScope=scope;data=view.series||[];previousDaySeries=view.previousDaySeries||[];currentChannels=view.currentChannels||{};previousChannels=view.previousChannels||{};const managementName=scope==='Full'?'Full Oficial':scope,summary=management.find(item=>item.grupo===managementName)||{gmv:0,pedidos:0,ticket:0},activeHour=Number(baseLiveMetrics.activeHour||0),hourGmv=view.hourlyUnavailable?0:data.reduce((sum,row)=>sum+Number(row.hours[activeHour]?.value||0),0),firstScopeLoad=!Object.values(previousChannels).some(Number);liveMetrics={...baseLiveMetrics,totalGmv:summary.gmv,totalOrders:summary.pedidos,ticket:summary.ticket,hourGmv,hourOrders:firstScopeLoad?summary.pedidos:baseLiveMetrics.hourOrders,hourIsReconciled:Boolean(baseLiveMetrics.hourIsReconciled||firstScopeLoad)};document.querySelector('#channelFilter').innerHTML='<option value="all">Todos os canais</option>'+data.map(d=>`<option>${d.channel}</option>`).join('');activeChannel='all';render()}
function renderAnalytics(){const q=document.querySelector('#analyticSearch').value.trim().toLowerCase(),company=document.querySelector('#analyticCompany').value,canal=document.querySelector('#analyticChannel').value,filtered=analyticData.filter(x=>(company==='all'||x.empresa===company)&&(canal==='all'||x.canal===canal)&&(!q||[x.pedido,x.empresa,x.canal,x.modalidade,x.marcadores,x.ecommerce,x.situacao].some(v=>String(v).toLowerCase().includes(q))));document.querySelector('#analyticOrders').textContent=new Intl.NumberFormat('pt-BR').format(analyticData.length);document.querySelector('#analyticGmv').textContent=money(analyticData.filter(x=>x.contabilizado).reduce((s,x)=>s+(+x.valor||0),0));document.querySelector('#analyticComplete').textContent=(analyticData.length?analyticData.filter(x=>x.detalhe==='Completo').length/analyticData.length*100:0).toFixed(0)+'%';document.querySelector('#analyticsRows').innerHTML=filtered.length?filtered.map(x=>`<tr><td><b>${x.pedido}</b></td><td>${x.empresa}</td><td><span class="channel-pill ${x.canal==='A identificar'?'warning':''}">${x.canal}</span></td><td><span class="mode-pill ${x.modalidade!=='Convencional'?'full':''}" title="${x.marcadores||''}">${x.modalidade||'Convencional'}</span></td><td>${x.ecommerce}</td><td>${x.situacao}</td><td class="${x.detalhe==='Completo'?'detail-complete':'detail-pending'}">${x.detalhe}</td><td>${fullMoney(x.valor)}</td></tr>`).join(''):'<tr><td colspan="8" class="empty-table">Nenhum pedido encontrado com os filtros selecionados.</td></tr>'}
function setupAnalytics(payload){analyticData=payload.analytics||[];management=payload.management||[];streamingStatus=payload.streaming||{};operational=payload.operational||{};const options=[...new Set(analyticData.map(x=>x.canal))].sort(),companies=[...new Set(analyticData.map(x=>x.empresa))].sort(),unidentified=payload.diagnostics?.unidentified||[],alert=document.querySelector('#dataQualityAlert');alert.hidden=!unidentified.length;alert.innerHTML=unidentified.length?`<strong>ATENÇÃO DE QUALIDADE</strong><span>${unidentified.length} pedido(s) ainda sem canal identificado. Eles permanecem visíveis para conciliação e não são ocultados.</span>`:'';document.querySelector('#analyticChannel').innerHTML='<option value="all">Todos os canais</option>'+options.map(x=>`<option>${x}</option>`).join('');document.querySelector('#analyticCompany').innerHTML='<option value="all">Todas as empresas</option>'+companies.map(x=>`<option>${x}</option>`).join('');renderManagement();renderOperational();renderAnalytics()}
async function loadBigQuery(update=false){const endpoint=update?'/api/update-data':`/api/data?date=${encodeURIComponent(selectedDate||'')}`;try{const response=await fetch(endpoint,{cache:'no-store'});if(!response.ok)throw new Error((await response.json()).error||'Falha na atualização');const payload=DASHBOARD_DATA.normalize(await response.json()),reconciliation=payload.reconciliation||{},retrying=reconciliation.status==='retrying';todayDate=payload.today||todayDate;selectedDate=payload.dataDate||selectedDate||todayDate;const picker=document.querySelector('#dashboardDate');picker.value=selectedDate;picker.max=todayDate;document.body.classList.toggle('historical-mode',Boolean(payload.isHistorical));comparisons=payload.comparisons||{};dailyTarget=Number(payload.target||0);isUpdating=Boolean(payload.updating)||reconciliation.status==='updating';document.querySelector('#updateStatus').classList.toggle('syncing',isUpdating||retrying);document.querySelector('#statusLabel').textContent=payload.isHistorical?'FECHAMENTO HISTÓRICO':retrying?`RECONCILIANDO ${reconciliation.pending||''} PEDIDOS`:isUpdating?'ATUALIZANDO EVENTOS':'ÚLTIMA ATUALIZAÇÃO';setupAnalytics(payload);snapshotHistory=payload.snapshotHistory||[];perspectiveViews=payload.views||[];baseLiveMetrics=payload.metrics||{};liveMetrics={...baseLiveMetrics};if(selectedDate===todayDate){const key='bf-chart-baseline-v3-'+selectedDate;try{chartBaseline=JSON.parse(localStorage.getItem(key)||'null')}catch{chartBaseline=null}if(!chartBaseline){const hour=Number(baseLiveMetrics.activeHour||new Date().getHours()),scopes={};for(const view of perspectiveViews)scopes[view.scope]={...(view.currentChannels||{})};chartBaseline={hour,createdAt:payload.updatedAt,scopes};localStorage.setItem(key,JSON.stringify(chartBaseline))}}else chartBaseline=null;if(payload.series?.length){hours.splice(0,hours.length,...payload.series[0].hours.map(h=>h.hour));applyConsolidated();if(payload.updatedAt)document.querySelector('#lastUpdate').textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(payload.updatedAt));return true}data=[];liveMetrics={totalOrders:0,ticket:0,hourGmv:0,hourOrders:0};currentChannels={};previousChannels={};document.querySelector('#channelFilter').innerHTML='<option value="all">Todos os canais</option>';renderEmpty();document.querySelector('#targetLabel').textContent=dailyTarget?money(dailyTarget):'SEM META';document.querySelector('#hourOrdersKpi').textContent='0';setComparison('dod',comparisons.dod,comparisons.previousDayGmv);setComparison('mom',comparisons.mom,comparisons.previousMonthGmv);if(update&&payload.waitingForLoad)toast('A primeira carga de hoje ainda não saiu');return true}catch(error){if(update)toast('Tiny: '+error.message);return false}}
document.querySelector('#refreshBtn').addEventListener('click',async e=>{e.currentTarget.classList.add('loading');try{const response=await fetch(`/api/update-data?date=${encodeURIComponent(selectedDate||todayDate||'')}`,{cache:'no-store'});if(!response.ok)throw new Error((await response.json()).error||'Falha na reconciliação');await loadBigQuery(false);toast(`Tiny reconciliado para ${(selectedDate||todayDate).split('-').reverse().join('/')}`)}catch(error){toast('Tiny: '+error.message)}finally{e.currentTarget.classList.remove('loading')}});
document.querySelector('#dashboardDate').addEventListener('change',async e=>{selectedDate=e.target.value;await loadBigQuery(false)});
document.querySelector('#channelFilter').innerHTML+=[...channels].map(c=>`<option>${c.name}</option>`).join('');document.querySelector('#channelFilter').addEventListener('change',e=>{activeChannel=e.target.value==='all'?'all':e.target.value;renderChart()});
document.querySelectorAll('.view-tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.view-tab,.report-view').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.querySelector('#'+button.dataset.view).classList.add('active')}));document.querySelector('#analyticSearch').addEventListener('input',renderAnalytics);document.querySelector('#analyticCompany').addEventListener('change',renderAnalytics);document.querySelector('#analyticChannel').addEventListener('change',renderAnalytics);
document.querySelector('#fileInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text(),lines=text.trim().split(/\r?\n/),sep=lines[0].includes(';')?';':',',head=lines.shift().split(sep).map(x=>x.trim().toLowerCase()),ci=head.findIndex(x=>['canal','channel'].includes(x)),hi=head.findIndex(x=>['hora','hour'].includes(x)),vi=head.findIndex(x=>['gmv','valor','value'].includes(x));if([ci,hi,vi].some(x=>x<0))throw Error();const map={};lines.forEach(l=>{const p=l.split(sep),name=p[ci].trim(),hour=p[hi].trim(),value=Number(p[vi].replace(/[^0-9,.-]/g,'').replace('.','').replace(',','.'));if(!map[name])map[name]={};map[name][hour]= (map[name][hour]||0)+value});const newHours=[...new Set(lines.map(l=>l.split(sep)[hi].trim()))];hours.splice(0,hours.length,...newHours);data=Object.entries(map).map(([channel,obj])=>({channel,hours:newHours.map(hour=>({hour,value:obj[hour]||0}))}));activeChannel='all';document.querySelector('#channelFilter').innerHTML='<option value="all">Todos os canais</option>'+data.map(d=>`<option>${d.channel}</option>`).join('');render();stamp();toast(`${data.length} canais importados com sucesso`)}catch{toast('CSV inválido. Use as colunas: hora, canal, gmv')}});
setInterval(()=>{const now=new Date(),e=document.querySelector('#liveClock');if(e)e.textContent=new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(now);const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);if(todayDate&&date!==todayDate&&selectedDate===todayDate){selectedDate=date;loadBigQuery(false)}},1000);setInterval(()=>loadBigQuery(false),60000);try{const stream=new EventSource('/api/events');stream.onmessage=()=>{if(selectedDate===todayDate)loadBigQuery(false)}}catch{}stamp();render();loadBigQuery(false);
try{const historicalStream=new EventSource('/api/events');historicalStream.onmessage=event=>{try{const message=JSON.parse(event.data);if(message.dataDate===selectedDate&&selectedDate!==todayDate)loadBigQuery(false)}catch{}}}catch{}
